import type { ReactNode } from 'react';
import { AlertCircle, CheckCircle2, RefreshCw, TriangleAlert } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { describeApiError, type ApiErrorCopy } from '@/lib/api-error';

interface QueryErrorAlertProps {
  error: unknown;
  onRetry: () => void;
  retrying?: boolean;
  title?: string;
  description?: string;
}

/** 查询失败：保留筛选/分页等现场，提供重试（对齐 Vue EzQueryError 的用途） */
export function QueryErrorAlert({
  error,
  onRetry,
  retrying,
  title = '列表未更新',
  description = '当前请求未能取得最新结果，筛选与分页位置已保留。',
}: QueryErrorAlertProps) {
  if (!error) {
    return null;
  }
  const copy = describeApiError(error, '请求失败，请稍后重试');
  return (
    <Alert variant="destructive" className="mb-4">
      <AlertCircle aria-hidden />
      <AlertTitle>{title}</AlertTitle>
      <AlertDescription>
        <p>{description}</p>
        <p className="mt-1">{copy.message}</p>
        {copy.traceId ? <p className="mt-1 font-mono text-xs">traceId: {copy.traceId}</p> : null}
        <Button variant="outline" size="sm" className="mt-2" disabled={retrying} onClick={onRetry}>
          <RefreshCw aria-hidden />
          {retrying ? '正在重试…' : '重新加载'}
        </Button>
      </AlertDescription>
    </Alert>
  );
}

interface MutationErrorAlertProps {
  error: unknown;
  title?: string;
  fallbackMessage?: string;
}

/** mutation 失败的行内错误反馈（对齐 Vue EzFormError 的用途，保留 traceId） */
export function MutationErrorAlert({
  error,
  title = '操作未完成',
  fallbackMessage = '操作失败，请稍后重试',
}: MutationErrorAlertProps) {
  if (!error) {
    return null;
  }
  const copy: ApiErrorCopy = describeApiError(error, fallbackMessage);
  return (
    <Alert variant="destructive">
      <AlertCircle aria-hidden />
      <AlertTitle>{title}</AlertTitle>
      <AlertDescription>
        <p>{copy.message}</p>
        {copy.traceId ? <p className="mt-1 font-mono text-xs">traceId: {copy.traceId}</p> : null}
      </AlertDescription>
    </Alert>
  );
}

/** 行内成功反馈（对齐 Vue message.success 的关键提示语） */
export function NoticeAlert({ children, onDismiss }: { children: ReactNode; onDismiss?: () => void }) {
  if (!children) {
    return null;
  }
  return (
    <Alert className="mb-4 border-success-border text-success">
      <CheckCircle2 aria-hidden />
      <AlertDescription className="flex items-center justify-between gap-2 [&_p]:leading-relaxed">
        <span>{children}</span>
        {onDismiss ? (
          <Button variant="ghost" size="sm" onClick={onDismiss}>
            知道了
          </Button>
        ) : null}
      </AlertDescription>
    </Alert>
  );
}

/** 通用警示条（对齐 Vue NAlert 的提示位），warning 三件套配色 */
export function WarningAlert({ children }: { children: ReactNode }) {
  return (
    <Alert className="mb-4 border-warning-border bg-warning-soft text-warning">
      <TriangleAlert aria-hidden />
      <AlertDescription>{children}</AlertDescription>
    </Alert>
  );
}
